Given a string s representing a non-negative integer, find the lexicographically previous permutation of its digits. Each digit of s must be used exactly once, and the resulting number must not contain leading zeros.If no previous permutation exists, return "-1".The answer should be returned as a string.Examples:Input: s = "4321"Output: "4312" Explanation:The lexicographically previous permutation of "4321" is "4312".Input: s = "1234"Output: "-1"Explanation: The string "1234" is sorted in ascending order, so no previous permutation exists.Try It YourselfTable of Content[Naive Approach] Generate All Permutations - O(|s| × |s|!) Time and O(|s|) Space[Expected Approach] Previous Permutation - O(|s|) Time and O(1) Space[Naive Approach] Generate All Permutations - O(|s| × |s|!) Time and O(|s|) SpaceThe idea is to generate all possible permutations of the digits of s using recursion (backtracking). For each permutation, we check whether it is valid,. Among all valid permutations, we keep track of the largest one. If no valid permutation exists, return “-1”.
            C++

    #include <bits/stdc++.h>
using namespace std;

// Stores the largest valid permutation smaller than the original string
string res;

// Backtracking function to generate all permutations
void generate(string &s, string &curr,
              vector<bool> &used, string &original) {

    // Base case: full permutation formed
    if (curr.size() == s.size()) {

        // Skip leading zero numbers
        if (curr[0] == '0') return;

        // Check if valid candidate
        if (curr < original) {
            if (res == "-1" || curr > res)
                res = curr;
        }
        return;
    }

    // Try each unused digit
    for (int i = 0; i < s.size(); i++) {

        if (used[i]) continue;

        used[i] = true;
        curr.push_back(s[i]);

        generate(s, curr, used, original);

        // Backtrack
        curr.pop_back();
        used[i] = false;
    }
}

// Function to find lexicographically previous permutation
string prevPermutation(string &s) {

    //  reset global variable for each call
    res = "-1";

    string curr = "";
    vector<bool> used(s.size(), false);

    generate(s, curr, used, s);

    return res;
}
int main() {

    string s = "4321";

    cout << prevPermutation(s);

    return 0;
}


